const t = wb.getWorksheet('Totals');
for (let r = 2; r <= 26; r++) {
  t.getRange(`B${r}`).setValue(`=SUM('Employee 1:Employee 3'!AB${r+3})`);
}
const rows:any[] = [];
for (let r = 2; r <= 26; r++) {
  const e = r+3;
  const code = t.getRange(`A${r}`).getValues()[0][0];
  const parts = ['Employee 1','Employee 2','Employee 3'].map(s => wb.getWorksheet(s));
  const codes = parts.map(s => s.getRange(`A${e}`).getValues()[0][0]);
  const vals = parts.map(s => s.getRange(`AB${e}`).getValues()[0][0] as number);
  const b = t.getRange(`B${r}`).getValues()[0][0];
  const indep = await wb.evaluate(`=COUNTIF('Employee 1'!$C$5:$AA$29,"${code}")+COUNTIF('Employee 2'!$C$5:$AA$29,"${code}")+COUNTIF('Employee 3'!$C$5:$AA$29,"${code}")`);
  rows.push([r, code, codes.every(c => c===code), vals.join('+'), b, indep, b===vals[0]+vals[1]+vals[2] && b===indep].join(' | '));
}
log(rows.join('\n'));
wb.getRange('Totals!A1:B26')

